'use client';
import {useMemo,useState} from 'react';
import type {Membership} from '@/lib/pilot';
import type {AccountingSetup} from '@/lib/accounting';
import {AccountingSetupAction} from '@/components/accounting-setup-action';
const standard=['receivable','accommodation','tax:city','tax:state','tax:lodging','tax:legacy','tax:unallocated','fee:resort','fee:technology','fee:unallocated','ota_fee','other_revenue'];
const labels:Record<string,string>={receivable:'Guest receivable',accommodation:'Accommodation','tax:city':'City tax','tax:state':'State tax','tax:lodging':'Lodging tax','fee:resort':'Resort fee','fee:technology':'Technology fee'};
export function AccountingMappingEditor({membership,setup}:{membership:Membership;setup:AccountingSetup}){
 const [components,setComponents]=useState<Record<string,string>>({...setup.current_mapping?.components}),[custom,setCustom]=useState(''),[extra,setExtra]=useState<string[]>([]),[error,setError]=useState('');
 const categories=[...new Set([...standard,...Object.keys(components),...extra])];
 const command=useMemo(()=>({kind:'mappings' as const,expectedVersion:setup.current_mapping?.version??0,components}),[components,setup.current_mapping?.version]);
 const compatible=(category:string,a:AccountingSetup['accounts'][number])=>a.active&&(category==='receivable'?a.kind==='asset':category.startsWith('tax:')?a.kind==='liability':['income','liability'].includes(a.kind));
 const invalid=Object.entries(components).some(([category,id])=>!setup.accounts.some(a=>a.account_id===id&&compatible(category,a)));
 if(membership.role!=='owner')return null;
 return <section aria-label="Edit posting mappings"><h3>Edit posting mappings</h3><p>Choose active accounts for each charge category. Unmapped categories cannot be posted when they contain an amount. Saving creates a new mapping version.</p>{categories.map(category=><label className="field" key={category}>{labels[category]??category}<select value={components[category]??''} onChange={e=>setComponents(old=>{const next={...old};if(e.target.value)next[category]=e.target.value;else delete next[category];return next;})}><option value="">Not mapped</option>{components[category]&&!setup.accounts.some(a=>a.account_id===components[category]&&compatible(category,a))&&<option value={components[category]} disabled>Unavailable account</option>}{setup.accounts.filter(a=>compatible(category,a)).map(a=><option key={a.account_id} value={a.account_id}>{a.code} · {a.name}</option>)}</select>{components[category]&&!setup.accounts.some(a=>a.account_id===components[category]&&compatible(category,a))&&<span>Choose an active account with a compatible type.</span>}</label>)}<label className="field">Custom tax or fee code<input placeholder="fee:cleaning" value={custom} onChange={e=>setCustom(e.target.value)}/></label><button className="secondary" onClick={()=>{if(!/^(tax|fee):[a-z][a-z0-9_]{0,79}$/.test(custom)){setError('Use tax:code or fee:code with lowercase letters, numbers and underscores.');return;}setExtra(old=>[...new Set([...old,custom])]);setCustom('');setError('');}}>Add category</button>{error&&<p role="alert">{error}</p>}{!components.receivable&&<p>Choose a guest receivable account before saving.</p>}{invalid&&<p role="alert">Resolve unavailable accounts before saving mappings.</p>}<AccountingSetupAction membership={membership} preview={invalid||!components.receivable?null:command}/></section>;
}
